<?php
require_once __DIR__.'/lib/members_lib.php';
$m=site_current_member();$allowed=$m&&!empty($m['file_share_access']);
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>파일 공유</title><style>
*{box-sizing:border-box}body{font-family:system-ui,-apple-system,sans-serif;background:#101114;color:#f2f2f2;margin:0;padding:16px}main{max-width:720px;margin:30px auto;background:#202228;padding:24px;border-radius:16px}a{color:#8cc8ff;overflow-wrap:anywhere}button,input{font:inherit}button{padding:11px 16px;background:#387cdb;color:white;border:0;border-radius:8px;cursor:pointer}button:disabled{opacity:.5}input[type=file]{max-width:100%;padding:14px 0}progress{display:block;width:100%;height:18px;margin:16px 0}#result{overflow-wrap:anywhere;line-height:1.8}small{color:#adb2bd}@media(max-width:600px){main{margin:0;padding:18px}button{min-height:44px}}
</style></head><body><main><h1>파일 공유</h1><p>파일당 최대 1GB · 전체 저장 공간 5GB · 업로드 완료 후 24시간 뒤 만료</p>
<?php if(!$m): ?><p>파일을 올리려면 회원 로그인이 필요합니다. <a href="/login.php">로그인</a></p><?php elseif(!$allowed): ?><p>파일 업로드는 관리자 권한 승인이 필요합니다.</p><?php else: ?>
<label for="file">파일 선택</label><input id="file" type="file"><div><button id="send" type="button">업로드</button></div><progress id="progress" max="100" value="0"></progress><p id="result" role="status" aria-live="polite"></p><small>업로드 중에는 이 페이지를 닫지 마세요. 연결이 끊기면 자동으로 재시도합니다. 브라우저를 닫으면 처음부터 다시 올려야 할 수 있습니다.</small>
<script>
const csrf=<?=json_encode(site_csrf(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const chunkSize=16*1024*1024;
async function call(action,data){const fd=new FormData();fd.append('action',action);fd.append('csrf',csrf);for(const [k,v] of Object.entries(data))fd.append(k,v);const response=await fetch('/file_share_api.php',{method:'POST',body:fd,credentials:'same-origin'});let result;try{result=await response.json()}catch(e){throw Error('서버 응답을 읽을 수 없습니다.')}if(!response.ok)throw Error(result.error||'요청을 처리하지 못했습니다.');return result;}
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function retry(action,data){let error;for(let i=0;i<3;i++){try{return await call(action,data)}catch(e){error=e;if(i<2)await sleep(1000*(i+1))}}throw error;}
document.getElementById('send').onclick=async()=>{const f=document.getElementById('file').files[0],btn=document.getElementById('send'),out=document.getElementById('result'),bar=document.getElementById('progress');if(!f)return;if(f.size<1||f.size>1073741824){out.textContent='1바이트 이상 1GB 이하의 파일을 선택해 주세요.';return;}btn.disabled=true;bar.value=0;out.textContent='업로드 중...';try{const started=await retry('start',{name:f.name,size:f.size});let offset=0;while(offset<f.size){const end=Math.min(offset+chunkSize,f.size);try{const sent=await call('chunk',{upload_id:started.upload_id,offset,chunk:f.slice(offset,end)});offset=sent.received;}catch(e){const state=await retry('status',{upload_id:started.upload_id});if(state.size!==f.size||state.received<offset||state.received>end)throw Error('업로드 상태가 일치하지 않습니다: '+e.message);if(state.received===offset){await sleep(1000);const sent=await retry('chunk',{upload_id:started.upload_id,offset,chunk:f.slice(offset,end)});offset=sent.received;}else{offset=state.received;}}bar.value=Math.round(offset/f.size*100);out.textContent='업로드 중 '+bar.value+'%';}
const finished=await retry('finish',{upload_id:started.upload_id});const url=location.origin+finished.url;const link=document.createElement('a');link.href=url;link.textContent=url;const copy=document.createElement('button');copy.type='button';copy.textContent='링크 복사';copy.onclick=async()=>{try{await navigator.clipboard.writeText(url);copy.textContent='복사 완료!'}catch(e){copy.textContent='위 링크를 직접 선택해 복사해 주세요.'}};out.replaceChildren(document.createTextNode('공유 링크: '),link,document.createElement('br'),copy);
}catch(e){out.textContent=e.message}finally{btn.disabled=false}};
</script><?php endif; ?><p><a href="/index.php">메인으로</a></p></main></body></html>
